const msg = $input.item.json.message;
return [{ json: {
  chatId: msg.chat.id,
  telegramUser: msg.from.id,
  nombreUsuario: msg.from.first_name || '',
  text: (msg.text || '').trim()
}}];

const entrada = $('Extraer entrada').item.json;
const filas = $input.all().map(i => i.json).filter(r => String(r.telegram_user) === String(entrada.telegramUser));
const session = filas.length ? filas[0] : null;
return [{ json: { ...entrada, session } }];

const item = $input.item.json;
const chatId = item.chatId;
const telegramUser = String(item.telegramUser);
const nombreUsuario = item.nombreUsuario || "";
const textoRaw = (item.text || "").trim();

const ADMIN_IDS = ["7975888104"];
const esAdmin = ADMIN_IDS.includes(telegramUser);

let session = item.session || null;
let pantalla = session ? session.pantalla_actual : "MENU_PRINCIPAL";
let paso = session ? session.paso_actual : "";
let datos = {};
try { datos = session && session.datos_parciales ? JSON.parse(session.datos_parciales) : {}; }
catch(e) { datos = {}; }

if (textoRaw.toLowerCase() === "miid") return [R(`🆔 Tu ID de Telegram es: ${telegramUser}

Admin: ${esAdmin ? "SI" : "NO"}`, pantalla, paso, datos)];

// ── Textos base ──────────────────────────────────────────────────────────────
const MENU_PRINCIPAL_TXT = `¿En qué te puedo ayudar hoy?

Menú principal:
0. Ayuda
1. Agenda (citas)
2. Tareas
3. Recordatorios
4. Hábitos
5. Listas
6. Reportes
7. Configuración
8. Administrador

Si quieres empezar rápido, te recomiendo la opción 1 (Agenda).`;

const BIENVENIDA = `Hola, soy AgendaBot 👋

Estoy aquí para ayudarte a organizar tus citas, tareas y recordatorios de forma sencilla y sin complicaciones.

Puedes escribirme en cualquier momento.
Para avanzar, solo tienes que escribir el número de la opción que quieras usar.

${MENU_PRINCIPAL_TXT}

Tip rápido: escribe solo el número (por ejemplo: 1) y presiona enviar.`;

const MENU_AGENDA_TXT = `Perfecto, vamos con tu agenda.

¿Qué deseas hacer?

1. Agendar una nueva cita
2. Consultar tu agenda
3. Reprogramar una cita
4. Cancelar una cita
5. Marcar una cita como completada
9. Volver al menú principal`;

const MENU_TAREAS_TXT = `Vamos con tus tareas.

¿Qué deseas hacer?

1. Crear tarea nueva
2. Ver tareas pendientes
3. Cambiar estado de tarea
9. Volver al menú principal`;

const MENU_HABITOS_TXT = `Vamos con tus hábitos.

¿Qué deseas hacer?

1. Crear nuevo hábito
2. Ver mis hábitos
3. Activar/Desactivar hábito
9. Volver al menú principal`;

const MENU_RECORDATORIOS_TXT = `Vamos con tus recordatorios.

¿Qué deseas hacer?

1. Crear recordatorio
2. Ver mis recordatorios
9. Volver al menú principal`;

const MENU_ADMIN_TXT = `Panel de administrador.

1. Ver usuarios
2. Ver logs recientes
9. Volver al menú principal`;

const MENU_REPORTES_TXT = `Reportes

1. Reporte diario
2. Reporte semanal
3. Productividad (tareas)
4. Hábitos (cumplimiento)
5. Agenda (estado de citas)
6. Productividad por usuario (reporte completo)
9. Volver al menú principal`;

const OPCION_INVALIDA = (opciones, pantallaNombre) =>
  `Ups, esa opción no existe en este menú.

Por favor escribe uno de los números que ves en pantalla.

Estás en: ${pantallaNombre}
Opciones disponibles: ${opciones}`;

// ── Helper central ───────────────────────────────────────────────────────────
function R(resp, nuevaPantalla, nuevoPaso, nuevosDatos, accion, opcionLog) {
  return { json: {
    chatId, telegramUser,
    respuesta: resp,
    nuevaPantalla,
    nuevoPaso: nuevoPaso || "",
    nuevosDatos: JSON.stringify(nuevosDatos || {}),
    accion: accion || "NINGUNA",
    pantallaLog: pantalla,
    opcionLog: opcionLog || textoRaw
  }};
}

// ── Validadores ──────────────────────────────────────────────────────────────
function esFechaValida(s) {
  if (!/^\d{4}-(0[1-9]|1[0-2])-(0[1-9]|[12]\d|3[01])$/.test(s)) return false;
  const [y,m,d] = s.split('-').map(Number);
  return new Date(y,m-1,d) >= new Date(new Date().setHours(0,0,0,0));
}
function esHoraValida(s) { return /^([01]\d|2[0-3]):([0-5]\d)$/.test(s); }

// ── Primer uso / /start ──────────────────────────────────────────────────────
if (!session)                              return [R(BIENVENIDA, "MENU_PRINCIPAL","",{})];
if (textoRaw.toLowerCase()==="/start")     return [R(MENU_PRINCIPAL_TXT,"MENU_PRINCIPAL","",{})];

// ═══════════════════════════════════════════════════════════════════════════════
switch (pantalla) {

// ── MENÚ PRINCIPAL ────────────────────────────────────────────────────────────
case "MENU_PRINCIPAL": {
  if (!/^[0-8]$/.test(textoRaw))
    return [R(OPCION_INVALIDA("0 al 8","Menú principal")+"

"+MENU_PRINCIPAL_TXT,"MENU_PRINCIPAL","",{})];
  switch(textoRaw){
    case "0": return [R(`Ayuda:
- Escribe el número de la opción deseada.
- Usa 9 para volver o cancelar en cualquier momento.

${MENU_PRINCIPAL_TXT}`,"MENU_PRINCIPAL","",{})];
    case "1": return [R(MENU_AGENDA_TXT,"MENU_AGENDA","",{})];
    case "2": return [R(MENU_TAREAS_TXT,"MENU_TAREAS","",{})];
    case "3": return [R(MENU_RECORDATORIOS_TXT,"MENU_RECORDATORIOS","",{})];
    case "4": return [R(MENU_HABITOS_TXT,"MENU_HABITOS","",{})];
    case "5": return [R(`Sección Listas 🚧

Próximamente.

${MENU_PRINCIPAL_TXT}`,"MENU_PRINCIPAL","",{})];
    case "6": return [R(MENU_REPORTES_TXT,"MENU_REPORTES","",{})];
    case "7": return [R(`Sección Configuración 🚧

Próximamente.

${MENU_PRINCIPAL_TXT}`,"MENU_PRINCIPAL","",{})];
    case "8":
      if (!esAdmin) return [R(`⛔ No tienes permisos para acceder a esta sección.

${MENU_PRINCIPAL_TXT}`,"MENU_PRINCIPAL","",{})];
      return [R(MENU_ADMIN_TXT,"MENU_ADMIN","",{})];
  }
  break;
}

// ═══════════════════════════════════════════════════════════════════════════════
// OPCIÓN 1 — AGENDA COMPLETA
// ═══════════════════════════════════════════════════════════════════════════════
case "MENU_AGENDA": {
  if (textoRaw==="9") return [R(MENU_PRINCIPAL_TXT,"MENU_PRINCIPAL","",{})];
  if (!/^[1-5]$/.test(textoRaw))
    return [R(OPCION_INVALIDA("1,2,3,4,5,9","Menú Agenda")+"

"+MENU_AGENDA_TXT,"MENU_AGENDA","",{})];
  if (textoRaw==="1") return [R(`Empecemos a crear tu cita.

Paso 1 de 6
¿Cuál es la fecha de la cita?

Formato: YYYY-MM-DD
Ejemplo: 2025-12-20

9. Cancelar`,"CITA_WIZARD","PASO1_FECHA",{})];
  if (textoRaw==="2") return [R(`📅 Consultar agenda

Escribe la fecha que deseas consultar:

Formato: YYYY-MM-DD
Ejemplo: 2025-12-20

9. Cancelar`,"AGENDA_CONSULTAR","PASO1_FECHA",{})];
  if (textoRaw==="3") return [R(`🔄 Reprogramar cita

Escribe el ID de la cita a reprogramar:
Ejemplo: CITA-123456

9. Cancelar`,"AGENDA_REPROGRAMAR","PASO1_ID",{})];
  if (textoRaw==="4") return [R(`❌ Cancelar cita

Escribe el ID de la cita a cancelar:
Ejemplo: CITA-123456

9. Cancelar`,"AGENDA_CANCELAR","PASO1_ID",{})];
  if (textoRaw==="5") return [R(`✅ Marcar cita como completada

Escribe el ID de la cita:
Ejemplo: CITA-123456

9. Cancelar`,"AGENDA_COMPLETAR","PASO1_ID",{})];
  break;
}

// — Wizard crear cita (6 pasos) ------------------------------------------------
case "CITA_WIZARD": {
  if (textoRaw==="9") return [R(`Operación cancelada.

${MENU_AGENDA_TXT}`,"MENU_AGENDA","",{})];
  if (paso==="PASO1_FECHA") {
    if (!esFechaValida(textoRaw)) return [R(`❌ Fecha inválida o en el pasado.

Formato: YYYY-MM-DD
Ejemplo: 2025-12-20

9. Cancelar`,"CITA_WIZARD","PASO1_FECHA",datos)];
    datos.fecha=textoRaw;
    return [R(`✅ Fecha: ${textoRaw}

Paso 2 de 6
¿A qué hora será la cita?

Formato 24 horas (HH:MM)
Ejemplo: 14:30

9. Cancelar`,"CITA_WIZARD","PASO2_HORA",datos)];
  }
  if (paso==="PASO2_HORA") {
    if (!esHoraValida(textoRaw)) return [R(`❌ Hora inválida.

Formato 24 horas (HH:MM)
Ejemplo: 14:30

9. Cancelar`,"CITA_WIZARD","PASO2_HORA",datos)];
    datos.hora=textoRaw;
    return [R(`✅ Hora: ${textoRaw}

Paso 3 de 6
¿A nombre de quién es la cita?

Escribe el nombre completo.

9. Cancelar`,"CITA_WIZARD","PASO3_NOMBRE",datos)];
  }
  if (paso==="PASO3_NOMBRE") {
    if (textoRaw.length<2) return [R(`❌ Escribe un nombre válido (mínimo 2 caracteres).

9. Cancelar`,"CITA_WIZARD","PASO3_NOMBRE",datos)];
    datos.nombre=textoRaw;
    return [R(`✅ Nombre: ${textoRaw}

Paso 4 de 6
Cuéntame brevemente el motivo de la cita.

Ejemplo: Asesoría técnica

9. Cancelar`,"CITA_WIZARD","PASO4_MOTIVO",datos)];
  }
  if (paso==="PASO4_MOTIVO") {
    if (textoRaw.length<2) return [R(`❌ Escribe un motivo válido.

9. Cancelar`,"CITA_WIZARD","PASO4_MOTIVO",datos)];
    datos.motivo=textoRaw;
    return [R(`✅ Motivo: ${textoRaw}

Paso 5 de 6
¿Cómo será la atención?

1. Presencial
2. Virtual
3. Llamada

9. Cancelar`,"CITA_WIZARD","PASO5_CANAL",datos)];
  }
  if (paso==="PASO5_CANAL") {
    const canales={"1":"Presencial","2":"Virtual","3":"Llamada"};
    if (!canales[textoRaw]) return [R(`❌ Elige 1 (Presencial), 2 (Virtual) o 3 (Llamada).

9. Cancelar`,"CITA_WIZARD","PASO5_CANAL",datos)];
    datos.canal=canales[textoRaw];
    const resumen=`Revisa la información de tu cita:

Fecha: ${datos.fecha}
Hora: ${datos.hora}
Cliente: ${datos.nombre}
Motivo: ${datos.motivo}
Canal: ${datos.canal}

¿Qué deseas hacer?
1. Confirmar y guardar
2. Editar información
3. Cancelar`;
    return [R(resumen,"CITA_WIZARD","PASO6_CONFIRMAR",datos)];
  }
  if (paso==="PASO6_CONFIRMAR") {
    if (textoRaw==="1") {
      const id="CITA-"+Date.now().toString().slice(-6);
      datos.id_generado=id;
      return [R(`¡Listo! Tu cita quedó agendada correctamente. ✅

ID de la cita: ${id}

¿Qué deseas hacer ahora?
1. Volver a Agenda
2. Ir al menú principal`,"POST_CITA","",datos,"GUARDAR_CITA")];
    }
    if (textoRaw==="2") return [R(`Empecemos de nuevo.

Paso 1 de 6
¿Cuál es la fecha de la cita?

Formato: YYYY-MM-DD

9. Cancelar`,"CITA_WIZARD","PASO1_FECHA",{})];
    if (textoRaw==="3") return [R(`Operación cancelada.

${MENU_AGENDA_TXT}`,"MENU_AGENDA","",{})];
    return [R(`Elige 1 (Confirmar), 2 (Editar) o 3 (Cancelar).`,"CITA_WIZARD","PASO6_CONFIRMAR",datos)];
  }
  break;
}
case "POST_CITA": {
  if (textoRaw==="1") return [R(MENU_AGENDA_TXT,"MENU_AGENDA","",{})];
  if (textoRaw==="2") return [R(MENU_PRINCIPAL_TXT,"MENU_PRINCIPAL","",{})];
  return [R(`Elige 1 (Volver a Agenda) o 2 (Menú principal).`,"POST_CITA","",datos)];
}

// — Consultar agenda -----------------------------------------------------------
case "AGENDA_CONSULTAR": {
  if (textoRaw==="9") return [R(MENU_AGENDA_TXT,"MENU_AGENDA","",{})];
  if (paso==="PASO1_FECHA") {
    if (!esFechaValida(textoRaw) && textoRaw!=="HOY")
      return [R(`❌ Fecha inválida.

Formato: YYYY-MM-DD
O escribe HOY para ver las citas de hoy.

9. Cancelar`,"AGENDA_CONSULTAR","PASO1_FECHA",datos)];
    const fechaBuscar = textoRaw==="HOY" ? new Date().toISOString().split("T")[0] : textoRaw;
    datos.fecha_consulta=fechaBuscar;
    return [R(`🔍 Buscando citas para el ${fechaBuscar}...

Resultado: No se encontraron citas registradas para esa fecha.

¿Deseas buscar otra fecha?
1. Buscar otra fecha
9. Volver a Agenda`,"AGENDA_CONSULTAR","PASO2_OPCIONES",datos)];
  }
  if (paso==="PASO2_OPCIONES") {
    if (textoRaw==="1") return [R(`📅 Consultar agenda

Escribe la fecha:

Formato: YYYY-MM-DD
O escribe HOY

9. Cancelar`,"AGENDA_CONSULTAR","PASO1_FECHA",{})];
    return [R(MENU_AGENDA_TXT,"MENU_AGENDA","",{})];
  }
  break;
}

// — Reprogramar cita -----------------------------------------------------------
case "AGENDA_REPROGRAMAR": {
  if (textoRaw==="9") return [R(MENU_AGENDA_TXT,"MENU_AGENDA","",{})];
  if (paso==="PASO1_ID") {
    if (!textoRaw.startsWith("CITA-"))
      return [R(`❌ ID inválido.

Ejemplo: CITA-123456

9. Cancelar`,"AGENDA_REPROGRAMAR","PASO1_ID",datos)];
    datos.id_cita=textoRaw;
    return [R(`🔄 Cita: ${textoRaw}

Escribe la nueva fecha:

Formato: YYYY-MM-DD
Ejemplo: 2025-12-25

9. Cancelar`,"AGENDA_REPROGRAMAR","PASO2_FECHA",datos)];
  }
  if (paso==="PASO2_FECHA") {
    if (!esFechaValida(textoRaw)) return [R(`❌ Fecha inválida o en el pasado.

Formato: YYYY-MM-DD

9. Cancelar`,"AGENDA_REPROGRAMAR","PASO2_FECHA",datos)];
    datos.nueva_fecha=textoRaw;
    return [R(`✅ Nueva fecha: ${textoRaw}

Escribe la nueva hora:

Formato: HH:MM
Ejemplo: 10:00

9. Cancelar`,"AGENDA_REPROGRAMAR","PASO3_HORA",datos)];
  }
  if (paso==="PASO3_HORA") {
    if (!esHoraValida(textoRaw)) return [R(`❌ Hora inválida.

Formato: HH:MM

9. Cancelar`,"AGENDA_REPROGRAMAR","PASO3_HORA",datos)];
    datos.nueva_hora=textoRaw;
    return [R(`¿Confirmas la reprogramación?

Cita: ${datos.id_cita}
Nueva fecha: ${datos.nueva_fecha}
Nueva hora: ${textoRaw}

1. Confirmar
2. Cancelar`,"AGENDA_REPROGRAMAR","PASO4_CONFIRMAR",datos)];
  }
  if (paso==="PASO4_CONFIRMAR") {
    if (textoRaw==="1") return [R(`✅ Cita ${datos.id_cita} reprogramada correctamente.

Nueva fecha: ${datos.nueva_fecha} a las ${datos.nueva_hora}

1. Volver a Agenda
2. Menú principal`,"POST_CITA","",datos,"ACTUALIZAR_CITA")];
    return [R(MENU_AGENDA_TXT,"MENU_AGENDA","",{})];
  }
  break;
}

// — Cancelar cita -------------------------------------------------------------
case "AGENDA_CANCELAR": {
  if (textoRaw==="9") return [R(MENU_AGENDA_TXT,"MENU_AGENDA","",{})];
  if (paso==="PASO1_ID") {
    if (!textoRaw.startsWith("CITA-"))
      return [R(`❌ ID inválido.

Ejemplo: CITA-123456

9. Cancelar`,"AGENDA_CANCELAR","PASO1_ID",datos)];
    datos.id_cita=textoRaw;
    return [R(`⚠️ ¿Confirmas que deseas CANCELAR la cita ${textoRaw}?

Esta acción no se puede deshacer.

1. Sí, cancelar cita
2. No, volver a Agenda`,"AGENDA_CANCELAR","PASO2_CONFIRMAR",datos)];
  }
  if (paso==="PASO2_CONFIRMAR") {
    if (textoRaw==="1") return [R(`✅ Cita ${datos.id_cita} cancelada correctamente.

1. Volver a Agenda
2. Menú principal`,"POST_CITA","",datos,"CANCELAR_CITA")];
    return [R(MENU_AGENDA_TXT,"MENU_AGENDA","",{})];
  }
  break;
}

// — Completar cita -------------------------------------------------------------
case "AGENDA_COMPLETAR": {
  if (textoRaw==="9") return [R(MENU_AGENDA_TXT,"MENU_AGENDA","",{})];
  if (paso==="PASO1_ID") {
    if (!textoRaw.startsWith("CITA-"))
      return [R(`❌ ID inválido.

Ejemplo: CITA-123456

9. Cancelar`,"AGENDA_COMPLETAR","PASO1_ID",datos)];
    datos.id_cita=textoRaw;
    return [R(`✅ ¿Confirmas que deseas marcar como COMPLETADA la cita ${textoRaw}?

1. Sí, marcar como completada
2. No, volver a Agenda`,"AGENDA_COMPLETAR","PASO2_CONFIRMAR",datos)];
  }
  if (paso==="PASO2_CONFIRMAR") {
    if (textoRaw==="1") return [R(`✅ Cita ${datos.id_cita} marcada como completada.

1. Volver a Agenda
2. Menú principal`,"POST_CITA","",datos,"COMPLETAR_CITA")];
    return [R(MENU_AGENDA_TXT,"MENU_AGENDA","",{})];
  }
  break;
}

// ═══════════════════════════════════════════════════════════════════════════════
// OPCIÓN 2 — TAREAS COMPLETAS
// ═══════════════════════════════════════════════════════════════════════════════
case "MENU_TAREAS": {
  if (textoRaw==="9") return [R(MENU_PRINCIPAL_TXT,"MENU_PRINCIPAL","",{})];
  if (!/^[1-3]$/.test(textoRaw))
    return [R(OPCION_INVALIDA("1,2,3,9","Menú Tareas")+"

"+MENU_TAREAS_TXT,"MENU_TAREAS","",{})];
  if (textoRaw==="1") return [R(`Vamos a crear tu tarea.

Paso 1 de 3
¿Cuál es el título de la tarea?

Ejemplo: Preparar informe mensual

9. Cancelar`,"TAREA_WIZARD","PASO1_TITULO",{})];
  if (textoRaw==="2") return [R(`📋 Consultando tus tareas...`,"MENU_TAREAS","",{},"VER_TAREAS")];
  if (textoRaw==="3") return [R(`🔄 Cambiar estado de tarea

Escribe el ID de la tarea:
Ejemplo: TAREA-123456

9. Cancelar`,"TAREA_ESTADO","PASO1_ID",{})];
  break;
}

// — Wizard crear tarea (3 pasos) -----------------------------------------------
case "TAREA_WIZARD": {
  if (textoRaw==="9") return [R(MENU_TAREAS_TXT,"MENU_TAREAS","",{})];
  if (paso==="PASO1_TITULO") {
    if (textoRaw.length<2) return [R(`❌ Escribe un título válido.

9. Cancelar`,"TAREA_WIZARD","PASO1_TITULO",datos)];
    datos.titulo=textoRaw;
    return [R(`✅ Título: ${textoRaw}

Paso 2 de 3
¿Cuál es la prioridad?

1. Alta
2. Media
3. Baja

9. Cancelar`,"TAREA_WIZARD","PASO2_PRIORIDAD",datos)];
  }
  if (paso==="PASO2_PRIORIDAD") {
    const prios={"1":"Alta","2":"Media","3":"Baja"};
    if (!prios[textoRaw]) return [R(`❌ Elige 1 (Alta), 2 (Media) o 3 (Baja).

9. Cancelar`,"TAREA_WIZARD","PASO2_PRIORIDAD",datos)];
    datos.prioridad=prios[textoRaw];
    return [R(`✅ Prioridad: ${datos.prioridad}

Paso 3 de 3
¿Cuál es la fecha objetivo?

Formato: YYYY-MM-DD
O escribe SIN si no tiene fecha límite.

9. Cancelar`,"TAREA_WIZARD","PASO3_FECHA",datos)];
  }
  if (paso==="PASO3_FECHA") {
    if (textoRaw!=="SIN" && !esFechaValida(textoRaw)) return [R(`❌ Fecha inválida.

Usa YYYY-MM-DD o escribe SIN.

9. Cancelar`,"TAREA_WIZARD","PASO3_FECHA",datos)];
    datos.fecha_objetivo=textoRaw;
    const id="TAREA-"+Date.now().toString().slice(-6);
    datos.id_generado=id;
    return [R(`¡Tarea creada correctamente! ✅

ID: ${id}
Título: ${datos.titulo}
Prioridad: ${datos.prioridad}
Fecha objetivo: ${textoRaw}
Estado: pendiente

1. Crear otra tarea
2. Ir al menú principal`,"POST_TAREA","",datos,"GUARDAR_TAREA")];
  }
  break;
}

// — Ver tareas ----------------------------------------------------------------
case "TAREA_VER": {
  if (textoRaw==="9") return [R(MENU_TAREAS_TXT,"MENU_TAREAS","",{})];
  if (paso==="PASO1_FILTRO") {
    return [R(`📋 Tareas pendientes:

No se encontraron tareas pendientes registradas.

Escribe 1 para crear una tarea o 9 para volver.`,"MENU_TAREAS","",{})];
  }
  break;
}

// — Cambiar estado tarea -------------------------------------------------------
case "TAREA_ESTADO": {
  if (textoRaw==="9") return [R(MENU_TAREAS_TXT,"MENU_TAREAS","",{})];
  if (paso==="PASO1_ID") {
    if (!textoRaw.startsWith("TAREA-")) return [R(`❌ ID inválido.

Ejemplo: TAREA-123456

9. Cancelar`,"TAREA_ESTADO","PASO1_ID",datos)];
    datos.id_tarea=textoRaw;
    return [R(`🔄 Tarea: ${textoRaw}

¿Cuál es el nuevo estado?

1. Pendiente
2. En progreso
3. Completada
4. Cancelada

9. Cancelar`,"TAREA_ESTADO","PASO2_ESTADO",datos)];
  }
  if (paso==="PASO2_ESTADO") {
    const estados={"1":"pendiente","2":"en_progreso","3":"completada","4":"cancelada"};
    if (!estados[textoRaw]) return [R(`❌ Elige una opción del 1 al 4.

