// ============================================================================
// LECTURA DE DATOS DESDE LAS 3 HOJAS (nodos leidos en cadena)
// ============================================================================
// IMPORTANTE - Mapeo real de columnas por hoja (verificado en AgendaBot_DB):
//   CITAS  -> el usuario que creó el registro está en la columna "creado_por"
//   TAREAS -> el usuario que creó el registro está en la columna "creado_por"
//   LOGS   -> el usuario está en la columna "telegram_user"
// Por eso NO se usa un único nombre de campo para las 3 hojas: cada una
// tiene su propio identificador de usuario y se normaliza aquí a un solo
// identificador interno ("user") para poder agrupar correctamente.
// ============================================================================

const citasData = $('Leer CITAS reportes').all().map(i => i.json);
const tareasData = $('Leer TAREAS reportes').all().map(i => i.json);
const logsData = $('Leer LOGS reportes').all().map(i => i.json);

const usuarios = {};

function inicializarUsuario(user) {
  if (!usuarios[user]) {
    usuarios[user] = {
      telegram_user: user,
      total_citas: 0,
      citas_completadas: 0,
      citas_canceladas: 0,
      total_tareas: 0,
      tareas_completadas: 0,
      tareas_pendientes: 0,
      interacciones: 0
    };
  }
}

// ============================================================================
// CRITERIO DE REGISTRO VÁLIDO (documentado):
// Un registro se considera válido si tiene un identificador de usuario no
// vacío en la columna correspondiente (creado_por en CITAS/TAREAS,
// telegram_user en LOGS). Registros sin ese campo, vacíos, o solo con
// espacios en blanco, se IGNORAN y no se cuentan en ninguna métrica.
// ============================================================================

// PROCESAR CITAS (columna real de usuario: "creado_por")
citasData.forEach(cita => {
  const rawUser = cita.creado_por;
  if (rawUser === undefined || rawUser === null) return;
  const user = String(rawUser).trim();
  if (!user) return;

  inicializarUsuario(user);
  usuarios[user].total_citas += 1;
  const estado = String(cita.estado || '').toLowerCase().trim();
  if (estado === 'completada') usuarios[user].citas_completadas += 1;
  if (estado === 'cancelada') usuarios[user].citas_canceladas += 1;
});

// PROCESAR TAREAS (columna real de usuario: "creado_por")
tareasData.forEach(tarea => {
  const rawUser = tarea.creado_por;
  if (rawUser === undefined || rawUser === null) return;
  const user = String(rawUser).trim();
  if (!user) return;

  inicializarUsuario(user);
  usuarios[user].total_tareas += 1;
  const estado = String(tarea.estado || '').toLowerCase().trim();
  if (estado === 'completada') usuarios[user].tareas_completadas += 1;
  else usuarios[user].tareas_pendientes += 1;
});

// PROCESAR LOGS (columna real de usuario: "telegram_user")
logsData.forEach(log => {
  const rawUser = log.telegram_user;
  if (rawUser === undefined || rawUser === null) return;
  const user = String(rawUser).trim();
  if (!user) return;

  inicializarUsuario(user);
  usuarios[user].interacciones += 1;
});

// ============================================================================
// ORDENAR ALFABÉTICAMENTE POR USUARIO
// ============================================================================
const usuariosArray = Object.values(usuarios).sort((a, b) =>
  String(a.telegram_user).toLowerCase().localeCompare(String(b.telegram_user).toLowerCase())
);

// ============================================================================
// RESUMEN GENERAL
// ============================================================================
const resumen = {
  total_citas_registradas: usuariosArray.reduce((sum, u) => sum + u.total_citas, 0),
  total_tareas_registradas: usuariosArray.reduce((sum, u) => sum + u.total_tareas, 0),
  total_interacciones_bot: usuariosArray.reduce((sum, u) => sum + u.interacciones, 0),
  usuario_mas_activo: usuariosArray.length > 0
    ? usuariosArray.reduce((max, u) => (u.interacciones > max.interacciones ? u : max)).telegram_user
    : 'N/A'
};

return [{ json: { resumen, usuarios: usuariosArray } }];

